from pathlib import Path
R=Path('/mnt/data/open-pathways-site')
nav=[('About Us','about-us.html'),('Getting Started','getting-started.html'),('Find Support','find-support.html'),('Resources','resource-center.html'),('Research','research.html'),('News & Events','news-events.html'),('Get Involved','get-involved.html'),('Contact','contact.html')]
def header():
 return '''<a class="skip" href="#main">Skip to content</a><div class="top"><div class="wrap"><span>Independent support for people with limb loss and limb difference.</span><span class="secondary">Accessible · Human · Empowering</span></div></div><header class="header"><div class="wrap nav"><a class="brand" href="index.html"><span class="mark">OP</span><span>Open Pathways<small>Limb Support Network</small></span></a><nav class="links" aria-label="Primary navigation">'''+''.join(f'<a href="{u}">{t}</a>' for t,u in nav)+'''</nav><div class="actions"><button class="icon" data-modal aria-label="Search">⌕</button><a class="btn soft" href="contact.html">Join Our Community</a><a class="btn primary" href="donate.html">Donate</a><button class="menu" aria-label="Open menu" aria-expanded="false">☰</button></div></div></header>'''
def footer():
 cols=[('ABOUT',[('About Us','about-us.html'),('Our Mission','about-us.html'),('Leadership','about-us.html'),('Financial Information','about-us.html'),('Contact','contact.html')]),('GET SUPPORT',[('Find Support','find-support.html'),('Resource Center','resource-center.html'),('Support Groups','support-groups.html'),('Peer Support','peer-support.html'),('Healthcare Navigation','healthcare-navigation.html')]),('PROGRAMS',[('Youth Programs','youth-programs.html'),('Caregiver Support','caregiver-resources.html'),('Events','events.html'),('Community Programs','find-support.html'),('Workforce Resources','get-involved.html')]),('GET INVOLVED',[('Donate','donate.html'),('Volunteer','volunteer.html'),('Join','contact.html'),('Advocacy','advocacy.html'),('Share Your Story','stories.html')])]
 return '<footer class="footer"><div class="wrap"><div class="footergrid"><div class="footerbrand"><div class="brand"><span class="mark">OP</span><span>Open Pathways<small style="color:#9eb4c0">Limb Support Network</small></span></div><p>Connecting people with trusted resources, peer support, education and community.</p><div class="social"><a href="#">f</a><a href="#">◎</a><a href="#">in</a><a href="#">▶</a></div></div>'+''.join('<div><h3>'+h+'</h3>'+''.join(f'<a href="{u}">{t}</a>' for t,u in links)+'</div>' for h,links in cols)+'</div><div class="bottom"><span>© 2026 Open Pathways Limb Support Network. All rights reserved.</span><span>Privacy · Terms · Accessibility · hello@openpathways.org · +1 (800) 555-0148</span></div></div></footer><div class="modal" role="dialog" aria-modal="true"><div class="modalbox"><button class="close" aria-label="Close">×</button><h2 style="font-size:1.8rem">Search Open Pathways</h2><p class="muted">Find resources, stories, events and support.</p><form class="form" data-form><input required placeholder="Search the site..." aria-label="Search query"><button class="btn primary">Search</button><div class="notice"></div></form></div></div><div class="toast"></div>'
def page(title,body):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Open Pathways</title><meta name="description" content="Open Pathways supports people with limb loss and limb difference through resources, connection and community."><link rel="stylesheet" href="styles.css"></head><body>{header()}<main id="main">{body}</main>{footer()}<script src="script.js"></script></body></html>'''
def hero(e,t,p):return f'<section class="pagehero"><div class="wrap"><div class="crumb">Home / {t}</div><div class="eyebrow">{e}</div><h1>{t}</h1><p>{p}</p></div></section>'
def cards(items,cls='g3'):
 return '<div class="grid '+cls+'">'+''.join(f'<article class="card reveal"{extra}><div class="iconbox">{i}</div><h3>{t}</h3><p>{d}</p><a class="cardlink" href="{u}">{a} →</a></article>' for i,t,d,u,a,extra in items)+'</div>'
def simple(title,e,intro,sections):return page(title,hero(e,title,intro)+''.join(f'<section class="section {c}"><div class="wrap">{h}</div></section>' for c,h in sections))
# Home
journeys=[('New to Limb Loss','Find guidance, resources, and support for your next steps.','getting-started.html','https://images.unsplash.com/photo-1550831107-1553da8c8464?auto=format&fit=crop&w=900&q=80'),('Youth & Young Adults','Discover mentorship, community, education, and opportunities.','youth-programs.html','https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=900&q=80'),('Family & Caregivers','Find information and support for yourself and your loved one.','caregiver-resources.html','https://images.unsplash.com/photo-1499209974431-9dddcece7f88?auto=format&fit=crop&w=900&q=80')]
help=[('♧','Peer Support','Connect with trained peers who understand lived experience.','peer-support.html'),('＋','Healthcare Navigation','Understand rehabilitation, care pathways and questions to ask.','healthcare-navigation.html'),('◌','Support Groups','Find welcoming spaces for conversation and connection.','support-groups.html'),('▤','Educational Resources','Clear, practical information for every stage.','resource-center.html'),('★','Youth Programs','Mentorship and community for young people and families.','youth-programs.html'),('♡','Caregiver Support','Tools and community for family members and caregivers.','caregiver-resources.html'),('↗','Workforce Resources','Explore workplace tools and employment resources.','get-involved.html'),('⚑','Adaptive Recreation','Discover ways to stay active and engaged.','find-support.html'),('⌁','Community Connections','Build relationships locally and online.','find-support.html')]
