home='''<section class="hero"><div class="wrap content"><div class="eyebrow">Open Pathways Limb Support Network</div><h1>Support, Connection, and Possibility</h1><p>Helping people with limb loss and limb difference find trusted resources, meaningful connections, and the support they need to move forward.</p><div class="hero-actions"><a class="btn primary" href="find-support.html">Find Support</a><a class="btn outline" href="contact.html">Join Our Community</a></div></div></section><section class="section"><div class="wrap"><div class="head"><div class="eyebrow">Your journey, your pace</div><h2>Where Are You in Your Journey?</h2><p>Whether everything is new or you're supporting someone you love, start with the path that feels right for you.</p></div>'''+journey_html+'''</div></section><section class="section alt"><div class="wrap split"><div class="photo reveal"><img alt="Person confidently walking outdoors with a prosthetic limb" src="https://images.unsplash.com/photo-1559757175-0eb30cd8c063?auto=format&fit=crop&w=1000&q=85"></div><div class="reveal"><div class="eyebrow">Our mission</div><h2>Helping People Live Fully Without Limits</h2><p>Open Pathways provides education, peer connection, practical resources and community programs for people with limb loss or limb difference. We believe informed choices and human connection can make every step forward feel more possible.</p><ul class="checks"><li>Trusted, plain-language information</li><li>Peer and community connection</li><li>Resources for families and caregivers</li><li>Support for accessible, active living</li></ul><a class="btn dark" href="about-us.html">Learn About Us</a></div></div></section><section class="section"><div class="wrap"><div class="stats reveal"><div class="stat"><strong data-count="40" data-suffix="+">0+</strong><span>Years of community support</span></div><div class="stat"><strong data-count="300" data-suffix="+">0+</strong><span>Support groups</span></div><div class="stat"><strong data-count="800" data-suffix="+">0+</strong><span>Peer support volunteers</span></div><div class="stat"><strong data-count="70" data-suffix="+">0+</strong><span>Educational fact sheets</span></div></div></div></section><section class="section alt"><div class="wrap"><div class="head"><div class="eyebrow">Support that meets you where you are</div><h2>How We Can Help</h2></div>'''+cards([(i,t,d,u,'Learn More', '') for i,t,d,u in help])+'''</div></section><section class="section"><div class="wrap"><div class="resource"><div class="eyebrow" style="color:#ffbea9">Resource center</div><h2>Resources for Every Step of Your Journey</h2><p>Browse practical guides, healthcare information, financial resources, rehabilitation tools and more.</p><div class="search"><input data-resource-search aria-label="Search resources" placeholder="Search our resources..."><button>Search</button></div></div></div></section><section class="section alt"><div class="wrap"><div class="newsletter reveal"><div><div class="eyebrow">Stay connected</div><h2 style="font-size:2.2rem">Useful resources, delivered.</h2><p>Receive community news, upcoming events and inspiring stories.</p></div><form class="form" style="width:min(470px,100%)" data-form><input type="email" required placeholder="Enter your email address" aria-label="Email address"><button class="btn primary">Subscribe</button><div class="notice"></div></form></div></div></section><section class="section"><div class="wrap"><div class="cta"><div><div class="eyebrow" style="color:#ffbea9">Make a difference</div><h2>Help Build a More Accessible Future</h2><p>Your support helps expand education, community programs, peer connection and practical resources.</p></div><div class="hero-actions"><a class="btn primary" href="donate.html">Donate Today</a><a class="btn outline" href="get-involved.html">Other Ways to Help</a></div></div></div></section>'''
(R/'index.html').write_text(page('Home',home))
