feature={
'about-us':('About Us','Our story','A welcoming nonprofit community for people with limb loss and limb difference, families, caregivers and allies.', [('A network built around people.','Open Pathways is an original nonprofit concept focused on making support easier to find and easier to trust. We connect people affected by limb loss or limb difference with practical information, peer relationships and community opportunities.'),('Our values','Human connection · Accessibility · Possibility · Trust')]),
'getting-started':('Getting Started','First steps',"You don't need to know everything today. Start with what matters right now.",[('Understand your care team','Learn who may be involved in rehabilitation and how to prepare questions.'),('Find people who understand','Explore peer support and groups where lived experience is valued.'),('Explore practical resources','Find guides about prosthetics, insurance, mobility and everyday life.'),('Look after your wellbeing','Find mental wellness and caregiver resources.')]),
'find-support':('Find Support','Support','Explore peer support, groups, healthcare navigation, youth programs and community connections.', [('Community Support','Find local and online spaces for conversation, activity and connection.'),('Peer Support','Request a conversation with a trained peer volunteer.'),('Healthcare Navigation','Prepare for appointments and explore care resources.'),('Youth & Young Adults','Find age-relevant programs and mentorship.'),('Caregiver Support','Resources for partners, parents, family members and caregivers.'),('Adaptive Recreation','Discover active and social opportunities.')]),
'caregiver-resources':('Caregiver Resources','Caregivers','Practical information and community support for parents, partners, relatives and other caregivers.', [('Care planning','Prepare questions and understand care pathways.'),('Emotional wellbeing','Find space for your own emotions and support needs.'),('Caregiver groups','Connect with others supporting a loved one.'),('Practical guides','Explore accessible guides for daily life and planning.')]),
'healthcare-navigation':('Healthcare Navigation','Healthcare','Practical navigation resources to help you prepare, ask questions and connect with appropriate care.', [('Rehabilitation','Learn about common rehabilitation roles and questions.'),('Preparing for appointments','Build a simple list of goals, questions and concerns.'),('Peer perspective','Connect with someone who can share lived experience.'),('Finding resources','Browse practical healthcare and accessibility information.')]),
'research':('Research','Evidence','Explore plain-language research resources and learn how to ask better questions about evidence.', [('Research summaries','Plain-language overviews of selected topics.'),('Community-informed questions','Themes that matter to people living everyday life.'),('Healthcare evidence','Resources for understanding rehabilitation and care conversations.')]),
'advocacy':('Advocacy','Access & participation','Informational resources about accessibility, healthcare access, prosthetic care and participation.', [('Accessibility','Learn about everyday accessibility and inclusive design.'),('Healthcare access','Explore resources for understanding care and coverage conversations.'),('Prosthetic care','Find educational resources and questions to discuss with professionals.'),('Opportunity','Explore inclusive work, recreation and participation.')]),
'get-involved':('Get Involved','Community','Give your time, skills, experience or support to help strengthen the community.', [('Donate','Help expand resources and community programs.'),('Volunteer','Support events, programs and community projects.'),('Join the community','Connect with people and opportunities.'),('Advocacy','Learn about accessibility and participation.'),('Share your story','Help others see that they are not alone.')]),
'youth-programs':('Youth Programs','Youth','Mentorship, community and opportunities for young people with limb loss or limb difference.', [('Mentorship','Build a supportive relationship with someone who has lived experience.'),('Youth Community','Join conversations and activities designed around connection.'),('Leadership','Explore opportunities to volunteer, speak and lead.'),('Adaptive Recreation','Discover movement and recreation opportunities.')]),
}
