    body=f'<div class="head"><h2>{items[0][0]}</h2><p>{items[0][1]}</p></div>'+cards(its,'g3')+f'<div class="cta" style="margin-top:28px"><div><h2>Need a next step?</h2><p>Explore more support or contact the Open Pathways team.</p></div><a class="btn primary" href="contact.html">Contact Support</a></div>'
    (R/(slug+'.html')).write_text(simple(title,e,intro,[('',body)]))
